\pset tuples_only on
\pset format unaligned
\pset fieldsep E'\t'
SELECT 'migration', migration FROM public.migrations ORDER BY migration;
SELECT 'table', n.nspname, c.relname, c.relkind::text, c.relrowsecurity::text, c.relforcerowsecurity::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.deptype='e') ORDER BY n.nspname,c.relname;
SELECT 'column', n.nspname, c.relname, a.attnum::text, a.attname, pg_catalog.format_type(a.atttypid,a.atttypmod), a.attnotnull::text, COALESCE(pg_get_expr(ad.adbin,ad.adrelid), '') FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef ad ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum WHERE n.nspname='public' AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.deptype='e') ORDER BY c.relname,a.attnum;
SELECT 'constraint', n.nspname, c.relname, con.conname, con.contype::text, regexp_replace(pg_get_constraintdef(con.oid,true), E'\\s+', ' ', 'g') FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.deptype='e') ORDER BY c.relname,con.conname;
SELECT 'index', n.nspname, t.relname, i.relname, ix.indisunique::text, ix.indisprimary::text, regexp_replace(pg_get_indexdef(ix.indexrelid), E'\\s+', ' ', 'g'), COALESCE(regexp_replace(pg_get_expr(ix.indpred,ix.indrelid), E'\\s+', ' ', 'g'),'') FROM pg_index ix JOIN pg_class t ON t.oid=ix.indrelid JOIN pg_class i ON i.oid=ix.indexrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=t.oid AND d.deptype='e') ORDER BY t.relname,i.relname;
SELECT 'trigger', n.nspname, c.relname, tg.tgname, tg.tgenabled::text, regexp_replace(pg_get_triggerdef(tg.oid,true), E'\\s+', ' ', 'g') FROM pg_trigger tg JOIN pg_class c ON c.oid=tg.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT tg.tgisinternal AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.deptype='e') ORDER BY c.relname,tg.tgname;
SELECT 'event_trigger', e.evtname, e.evtevent, e.evtenabled::text, p.oid::regprocedure::text, COALESCE(array_to_string(e.evttags,','),'') FROM pg_event_trigger e JOIN pg_proc p ON p.oid=e.evtfoid ORDER BY e.evtname;
SELECT 'policy', schemaname, tablename, policyname, permissive, array_to_string(roles,','), cmd, COALESCE(regexp_replace(qual,E'\\s+',' ','g'),''), COALESCE(regexp_replace(with_check,E'\\s+',' ','g'),'') FROM pg_policies WHERE schemaname='public' ORDER BY tablename,policyname;
SELECT 'function', n.nspname, p.proname, pg_get_function_identity_arguments(p.oid), p.prosecdef::text, COALESCE(array_to_string(p.proconfig,','),''), regexp_replace(pg_get_functiondef(p.oid), E'\\s+', ' ', 'g') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e') ORDER BY p.proname,pg_get_function_identity_arguments(p.oid);
SELECT 'function_acl', n.nspname, p.proname, pg_get_function_identity_arguments(p.oid), x.grantee::regrole::text, x.privilege_type, x.is_grantable::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl, acldefault('f',p.proowner))) x WHERE n.nspname='public' AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e') ORDER BY p.proname,pg_get_function_identity_arguments(p.oid),x.grantee::regrole::text,x.privilege_type;
SELECT 'table_acl', table_schema, table_name, grantee, privilege_type, is_grantable FROM information_schema.table_privileges WHERE table_schema='public' ORDER BY table_name,grantee,privilege_type;
SELECT 'sequence', n.nspname, c.relname, s.seqtypid::regtype::text, s.seqstart::text, s.seqincrement::text, s.seqmin::text, s.seqmax::text, s.seqcache::text, s.seqcycle::text FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' ORDER BY c.relname;
SELECT 'geometry', f_table_schema, f_table_name, f_geometry_column, coord_dimension::text, srid::text, type FROM public.geometry_columns WHERE f_table_schema='public' ORDER BY f_table_name,f_geometry_column;
